return UnityEngine.Resources.FindObjectsOfTypeAll<UnityEngine.GameObject>().Where(g=>g.name.StartsWith("Nature - ")).SelectMany(g=>g.GetComponentsInChildren<UnityEngine.MeshFilter>()).Where(f=>f.GetComponent<UnityEngine.Renderer>()!=null).Select(f=>new {name=f.sharedMesh.name, readable=f.sharedMesh.isReadable, vertices=f.sharedMesh.vertexCount}).GroupBy(x=>x.name).Select(g=>g.First()).ToArray();
